<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import { LockKeyhole } from '@lucide/vue'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import EditorDialog from '@/components/business/EditorDialog.vue'
import PasswordInput from '@/components/business/PasswordInput.vue'
import ErrorNotice from '@/components/business/ErrorNotice.vue'
import { useSecurityControls } from '@/composables/useSecurityControls'
const { t } = useI18n()
const props = defineProps<{ beforeExit?: () => Promise<boolean> }>()
const { auth, passwordOpen, oldPassword, newPassword, confirmation, unlockPassword, passwordBusy, passwordUnknown, canCheckPassword,
  sessionBusy, lockUnknown, locked, exiting, querying, error, openPassword, save, checkPassword, lock, unlock, logout } = useSecurityControls(() => props.beforeExit?.() || Promise.resolve(true))
defineExpose({ openPassword, lock, logout })
</script>
<template><EditorDialog v-model="passwordOpen" :title="t('auth.changePassword')" :busy="passwordBusy" :submit-disabled="passwordUnknown" :dirty="!!oldPassword || !!newPassword || !!confirmation" @save="save"><ErrorNotice :message="error" /><Button v-if="canCheckPassword" type="button" variant="outline" :disabled="passwordBusy" @click="checkPassword">{{ t(querying ? 'common.loading' : 'common.operation.check') }}</Button><form class="space-y-4" @submit.prevent="save"><div class="space-y-2"><Label for="old-password">{{ t('auth.oldPassword') }}</Label><PasswordInput id="old-password" v-model="oldPassword" autocomplete="current-password" :disabled="passwordBusy || passwordUnknown" /></div><div class="space-y-2"><Label for="new-password">{{ t('auth.newPassword') }}</Label><PasswordInput id="new-password" v-model="newPassword" autocomplete="new-password" :disabled="passwordBusy || passwordUnknown" /></div><div class="space-y-2"><Label for="confirm-password">{{ t('auth.confirmPassword') }}</Label><PasswordInput id="confirm-password" v-model="confirmation" autocomplete="new-password" :disabled="passwordBusy || passwordUnknown" /></div><button type="submit" hidden tabindex="-1" aria-hidden="true">{{ t('common.save') }}</button></form></EditorDialog><Dialog :open="locked"><DialogContent :show-close-button="false" class="sm:max-w-sm" @escape-key-down.prevent @pointer-down-outside.prevent @interact-outside.prevent><DialogHeader><div class="mx-auto mb-3 flex size-12 items-center justify-center rounded-xl bg-accent text-primary"><LockKeyhole class="size-6" /></div><DialogTitle class="text-center">{{ t('auth.locked') }}</DialogTitle><DialogDescription class="text-center">{{ auth.user?.name }}</DialogDescription></DialogHeader><ErrorNotice :message="error" /><form class="space-y-4" @submit.prevent="unlock"><Label for="unlock-password">{{ t('auth.password') }}</Label><PasswordInput id="unlock-password" v-model="unlockPassword" autocomplete="current-password" :disabled="sessionBusy || lockUnknown || exiting" /><Button class="w-full" type="submit" :disabled="sessionBusy || lockUnknown || exiting || !unlockPassword">{{ t(sessionBusy ? 'common.loading' : 'auth.unlock') }}</Button><Button class="w-full" variant="ghost" type="button" :disabled="exiting" @click="logout">{{ t('common.signOut') }}</Button></form></DialogContent></Dialog></template>
